mapper.update:
UPDATE rate_plan_promotions SET rate_plan_id=#{ratePlanId}, code=#{code}, name=#{name}, promotion_type=#{promotionType},
    discount_percent=#{discountPercent}, priority=#{priority}, stay_start=#{stayStart}, stay_end=#{stayEnd},
    book_start=#{bookStart}, book_end=#{bookEnd}, min_advance_days=#{minAdvanceDays}, max_advance_days=#{maxAdvanceDays},
    min_nights=#{minNights}, days_of_week=#{daysOfWeek}::jsonb, status=#{status},
    data_version=data_version+1, updated_by=#{updatedBy}, updated_at=#{updatedAt}
WHERE id=#{id} AND data_version=#{dataVersion}

mapper.select:
SELECT * FROM rate_plan_promotions WHERE hotel_id=#{hotelId}
AND status='ENABLED'
ORDER BY priority ASC, discount_percent DESC, created_at ASC
